def l1TailNorms (e : ℕ → X) (N : ℕ) : Set ℝ :=
  {t | ∃ b : ℕ →₀ ℂ, (∀ i ∈ b.support, N ≤ i) ∧
    coefficientL1Mass b = 1 ∧ t = ‖Finsupp.linearCombination ℂ e b‖}

